const token=prompt('Enter the admin token'),auth={Authorization:'Bearer '+token,'Content-Type':'application/json'},$=s=>document.querySelector(s);async function req(u,b){const r=await fetch(u,{method:b?'POST':'GET',headers:auth,body:b?JSON.stringify(b):undefined}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}async function render(){try{const d=await req('/api/admin/status'),p=d.meta.feed_paused==='true',f=d.file;$('#export-dir').value='RACE_EXPORT_DIR='+d.sourceConfig.hostDirectory;$('#export-filename').value='RACE_EXPORT_FILENAME='+d.sourceConfig.filename;$('#app-version').textContent='Version '+d.version;$('#file-status').textContent=f.exists?`Reading ${f.configured} · ${f.bytes} bytes`:`Waiting for ${f.configured}`;$('#import-status').textContent=d.meta.last_error?'Last error: '+d.meta.last_error:'Last successful import: '+(d.meta.last_import||'waiting');$('#event-status').value=d.meta.status||'Live';$('#event-status').onchange=()=>req('/api/admin/status',{status:$('#event-status').value});$('#feed-toggle').textContent=p?'Start live updates':'Stop live updates ('+d.pollSeconds+'s)';$('#feed-toggle').onclick=async()=>{await req('/api/admin/feed',{running:p});render()};$('#event-list').innerHTML=d.events.map(e=>`<div class="event-row"><div><h3>${e.name}</h3><p>${e.count} imported results · ${e.visible?'Visible publicly':'Hidden'}</p></div><label class="switch"><input type="checkbox" data-id="${e.id}" ${e.visible?'checked':''}><span class="slider"></span></label></div>`).join('');$('#event-list').querySelectorAll('input').forEach(x=>x.onchange=async()=>{await req('/api/admin/events/'+encodeURIComponent(x.dataset.id),{visible:x.checked});render()})}catch(e){$('#event-list').textContent=e.message}}render();

